export function evaluate({ inputs, time }) {
  const g = 9.8;
  const v0 = Number(inputs.launchSpeed);
  const apexTime = v0 / g;
  const apexHeight = (v0 * v0) / (2 * g);
  const t = Math.min(time, 2 * apexTime);
  const velocity = v0 - g * t;
  const height = v0 * t - 0.5 * g * t * t;

  let motionState = 'Still for an instant';
  if (Math.abs(velocity) > 0.05) {
    motionState = velocity > 0 ? 'Moving up' : 'Moving down';
  }
  const gravityState = 'Gravity pulls down';

  const xCenter = 260;
  const yLaunch = 340;
  const pixelsPerMeter = 120;
  const yPos = yLaunch - height * pixelsPerMeter;

  const objects = [];

  const panelObjs = sdk.panel({
    id: 'lane.main',
    x: 20,
    y: 30,
    w: 600,
    h: 370,
    title: 'Vertical Toss',
    state: motionState
  });
  objects.push(...panelObjs);

  const axisObj = sdk.axis('axis.height', {
    x: 80,
    y: yLaunch,
    length: 280,
    orientation: 'y',
    min: 0,
    max: 2.5,
    ticks: [0, 0.5, 1.0, 1.5, 2.0, 2.5],
    label: 'Height',
    unit: 'm'
  });
  objects.push(axisObj);

  const guideLine = sdk.line('guide.launch', 120, yLaunch, 420, yLaunch, {
    opacity: 0.5,
    role: 'neutral'
  });
  const guideText = sdk.text('text.launchGuide', 425, yLaunch + 4, 'Launch height (0 m)', {
    align: 'start',
    role: 'neutral'
  });
  objects.push(guideLine, guideText);

  const ballObj = sdk.circle('ball.toss', xCenter, yPos, 28, {
    role: 'learner'
  });
  objects.push(ballObj);

  const vVec = sdk.vector('vec.v', { x: xCenter - 30, y: yPos }, {
    value: velocity,
    direction: 'up',
    scale: 18,
    minLength: 12,
    label: 'v',
    role: 'output'
  });
  objects.push(...vVec);

  const aVec = sdk.vector('vec.a', { x: xCenter + 30, y: yPos }, {
    value: -g,
    direction: 'up',
    scale: 6,
    minLength: 12,
    label: 'a (gravity)',
    role: 'warning'
  });
  objects.push(...aVec);

  const calloutObjs = sdk.callout(xCenter + 70, yPos - 15, [motionState, gravityState], {
    id: 'callout.toss',
    role: 'neutral'
  });
  objects.push(...calloutObjs);

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: 'motionState', value: motionState },
        { id: 'gravityState', value: gravityState }
      ]
    },
    quantities: {
      launchSpeed: v0,
      gravity: g,
      apexTime,
      apexHeight,
      velocity,
      height
    }
  };
}
